head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnClass]<br/>Body Column 정보를 사용하여 특정 Body Column 에 설정된 CSS 클래스를 반환합니다.",
    "validation" : [
        "setColumnClass() 메소드로 설정한 CSS 클래스만 반환됩니다.",
        "columnInfo(필수) 파라미터로 조회할 Body Column 의 인덱스를 설정합니다. (인덱스 0부터, 숨겨진 Column 도 포함하여 인덱스 설정)",
        "설정된 CSS 클래스가 없는 경우 undefined 를 반환합니다.",
        "setColumnClass() 실행 시 CSS 클래스는 Body Column 에 속한 모든 Cell 의 td 요소에 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 생성 (가장 먼저)
    $c.gcm.createLabel('label="Column 인덱스 1 (col2) 은 숨김 처리되어 있으며, 숨겨진 Column 도 인덱스에 포함됩니다."', '', 'label1');

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성 (기본 4행)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성 (Body Column 인덱스: col1(0) ~ col4(3))
    await $c.gcm.createBasicGridView(cList);

    // Column 인덱스 1 (col2) 숨김 처리
    target1.setColumnVisible(1, false);
}



scwin.btn_setColumnClass_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let className = par_className.getText();

    // Column 인덱스로 Body Column 에 CSS 클래스 설정
    target1.setColumnClass(columnInfo, className);
    wf_body_bottom.getObj("scwin").setReturnValue("setColumnClass(" + columnInfo + ", " + className + ")");
}



scwin.btn_getColumnClass_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());

    // Column 인덱스로 설정된 CSS 클래스 반환 (setColumnClass 로 설정한 값만 반환, 미설정 시 undefined)
    let rtn = target1.getColumnClass(columnInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getColumnClass(" + columnInfo + ") : " + rtn);

    // (@spec) 설정된 CSS 클래스가 Body Column 에 속한 모든 Cell 의 td 요소에 적용되었는지 확인
    //  - getRowCount() 만큼만 출력 (데이터 행 외 viewport 를 채우는 빈 행은 제외)
    let tdList = document.querySelectorAll("td[id*='target1_cell_'][id$='_" + columnInfo + "']");
    for (let i = 0; i < target1.getRowCount(); i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("Row " + i + " td className : " + tdList[i].className);
    }
}
